//! Fixture A (`fixtures/tiny`, generated by `tools/gen_tiny.py`) through the
//! graph: the ONNX graph laid onto the DR#3 tile, every node resolved to its
//! op-signature classid, its WHEN evaluated, its DO run. ORT (`ORT_DISABLE_ALL`,
//! the literal semantics) is read from `fixtures/tiny/ort.json`; execution
//! never calls Tract or ORT.

use dr_math_binding_probe::FrameStore;
use ndarray::{ArrayD, IxDyn};
use serde_json::Value as Json;
use tract_harvest_probe::dr3::{tract_facts, OnnxGraph};
use tract_harvest_probe::plan::{resolve, revisions, Plan};
use tract_harvest_probe::registry::{registry, Refusal, Registry, K3};
use tract_harvest_probe::source::SourceInventory;
use tract_harvest_probe::value::Value;
use tract_onnx::prelude::Framework;

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/tiny");

fn bytes(v: &str) -> Vec<u8> {
    std::fs::read(format!("{DIR}/{v}.onnx")).unwrap()
}

fn ort() -> Json {
    serde_json::from_str(&std::fs::read_to_string(format!("{DIR}/ort.json")).unwrap()).unwrap()
}

fn u32s(v: &Json) -> Vec<u32> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|b| b.as_u64().unwrap() as u32)
        .collect()
}

fn f32_value(shape: &[usize], bits: &[u32]) -> Value {
    Value::F32(
        ArrayD::from_shape_vec(
            IxDyn(shape),
            bits.iter().map(|&b| f32::from_bits(b)).collect(),
        )
        .unwrap(),
    )
}

fn inputs(f_bits: Option<&[u32]>) -> Vec<(&'static str, Value)> {
    let o = ort();
    let x: Vec<i32> = o["inputs"]["X"]["bits"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_i64().unwrap() as i32)
        .collect();
    let f = f_bits
        .map(<[u32]>::to_vec)
        .unwrap_or_else(|| u32s(&o["inputs"]["F"]["bits"]));
    vec![
        (
            "X",
            Value::I32(ArrayD::from_shape_vec(IxDyn(&[x.len()]), x).unwrap()),
        ),
        ("F", f32_value(&[2, 3], &f)),
    ]
}

fn ort_out(v: &str) -> (i32, Vec<u32>) {
    let e = &ort()["variants"][v]["ort"];
    (
        e["S"]["bits"][0].as_i64().unwrap() as i32,
        u32s(&e["Q"]["bits"]),
    )
}

struct Fixture {
    store: FrameStore,
    src: SourceInventory,
}

fn graph(v: &str) -> (SourceInventory, OnnxGraph) {
    let b = bytes(v);
    let src = SourceInventory::from_bytes(&b).unwrap();
    let facts = tract_facts(&b, &[]).unwrap();
    let g = OnnxGraph::build(&src, &facts).unwrap();
    (src, g)
}

fn plan<'r>(v: &str, reg: &'r Registry) -> (Fixture, Result<Plan<'r>, Refusal>) {
    let (src, g) = graph(v);
    let store = FrameStore::new(revisions(&src, reg, &g));
    let p = resolve(&src, g, reg, &store);
    (Fixture { store, src }, p)
}

fn outputs(m: &std::collections::HashMap<String, Value>) -> (i32, Vec<u32>) {
    let s = match &m["S"] {
        Value::I32(a) => {
            assert_eq!(a.shape(), &[] as &[usize], "keepdims=0 gives a scalar");
            a.iter().copied().next().unwrap()
        }
        other => panic!("{other:?}"),
    };
    let q = match &m["Q"] {
        Value::F32(a) => {
            assert_eq!(a.shape(), &[2, 3]);
            a.iter().map(|v| v.to_bits()).collect()
        }
        other => panic!("{other:?}"),
    };
    (s, q)
}

/// The graph runs node by node through registered methods and agrees with ORT
/// bit for bit. Every node got a classid; none is a pattern recipe.
#[test]
fn base_through_the_graph_is_bit_exact_against_ort() {
    let reg = registry();
    let (fx, p) = plan("base", &reg);
    let p = p.unwrap();
    let names: Vec<&str> = p.steps.iter().map(|s| s.name.as_str()).collect();
    assert_eq!(
        names,
        [
            "n_greater",
            "n_where",
            "n_reducesum",
            "n_add",
            "n_mul",
            "n_abs",
            "n_sqrt",
            "n_div"
        ]
    );
    let cids: Vec<u16> = p.steps.iter().map(|s| s.classid).collect();
    assert_eq!(
        cids,
        [0x0F50, 0x0F51, 0x0F41, 0x0F20, 0x0F22, 0x0F30, 0x0F31, 0x0F23]
    );
    assert_eq!(
        outputs(&p.run(&fx.store, &inputs(None)).unwrap()),
        ort_out("base")
    );
}

/// `dep = do_ ∘ read_by` is exactly the source dataflow (no more, no less),
/// and the schedule is a topological order of it.
#[test]
fn dep_composition_is_the_source_dataflow() {
    for v in ["base", "div3", "neg_where_nonzero"] {
        let (_, g) = graph(v);
        let (dep, work) = g.dep();
        assert_eq!(dep, g.dep_from_edges(), "{v}");
        assert!(
            dep.iter().any(|&r| r != 0),
            "{v}: anti-vacuity, there are edges"
        );
        assert!(work.row_ors > 0);
        let order = g.schedule().unwrap();
        let pos: Vec<usize> = (0..g.nodes)
            .map(|n| order.iter().position(|&o| o == n).unwrap())
            .collect();
        for (i, row) in dep.iter().enumerate().take(g.nodes) {
            for j in 0..g.nodes {
                if row >> j & 1 == 1 {
                    assert!(pos[i] < pos[j], "{v}: {i} before {j}");
                }
            }
        }
    }
}

/// `Where(c, X, 1)` (ORT: 17). With the graph there is no masked-sum rewrite to
/// refuse: `Where` and `ReduceSum` are separate registered methods, and the
/// graph runs and matches ORT.
#[test]
fn where_with_nonzero_else_runs_and_matches_ort() {
    let reg = registry();
    let (fx, p) = plan("neg_where_nonzero", &reg);
    assert_eq!(ort_out("neg_where_nonzero").0, 17);
    assert_eq!(
        outputs(&p.unwrap().run(&fx.store, &inputs(None)).unwrap()),
        ort_out("neg_where_nonzero")
    );
}

/// `div3` over 256 seeded inputs: the graph keeps `Div` (classid 0x0F23) and
/// matches ORT bit for bit on every element.
#[test]
fn div3_sweep_is_bit_exact() {
    let reg = registry();
    let (fx, p) = plan("div3", &reg);
    let p = p.unwrap();
    let o = ort();
    let sweep = &o["div3_sweep"];
    let fs = sweep["F_bits"].as_array().unwrap();
    assert_eq!(fs.len(), 256);
    for (fb, qb) in fs.iter().zip(sweep["Q_bits"].as_array().unwrap()) {
        let out = p.run(&fx.store, &inputs(Some(&u32s(fb)))).unwrap();
        assert_eq!(outputs(&out).1, u32s(qb));
    }
}

/// A plan sealed for `base` refuses to run once the store advances to `gen2`
/// (same shapes, new `B` bytes); `gen2` resolved on its own matches its ORT.
#[test]
fn stale_generation_is_refused() {
    let reg = registry();
    let (mut fx, p) = plan("base", &reg);
    let p = p.unwrap();
    let (src2, g2) = graph("gen2");
    let r2 = revisions(&src2, &reg, &g2);
    assert_eq!(r2.relation_map, fx.store.revisions().relation_map);
    assert_eq!(
        r2.coordinates,
        fx.store.revisions().coordinates,
        "same positions"
    );
    assert_ne!(r2.source, fx.store.revisions().source);
    fx.store.advance(r2);
    match p.run(&fx.store, &inputs(None)) {
        Err(Refusal::Frame(dr_math_binding_probe::Refusal::SourceChanged)) => {}
        other => panic!("{:?}", other.map(|_| ())),
    }
    let _ = &fx.src;
    let reg2 = registry();
    let (fx2, p2) = plan("gen2", &reg2);
    assert_eq!(
        outputs(&p2.unwrap().run(&fx2.store, &inputs(None)).unwrap()),
        ort_out("gen2")
    );
}

/// A registry with another version is another frame: a plan sealed under v1
/// refuses once the store moves to the v2 map.
#[test]
fn registry_change_is_a_frame_change() {
    let reg = registry();
    let (mut fx, p) = plan("base", &reg);
    let p = p.unwrap();
    let mut r = fx.store.revisions();
    r.relation_map += 1;
    fx.store.advance(r);
    match p.run(&fx.store, &inputs(None)) {
        Err(Refusal::Frame(dr_math_binding_probe::Refusal::MapChanged)) => {}
        other => panic!("{:?}", other.map(|_| ())),
    }
}

/// `B[4]` against `F[2,3]`: ORT refuses at load; Tract types it. The Add's WHEN
/// (multidirectional broadcast over the facts) is FALSE, so resolution refuses
/// before anything runs.
#[test]
fn incompatible_broadcast_is_when_false() {
    assert!(ort()["variants"]["neg_shape"]["ort_error"]
        .as_str()
        .unwrap()
        .contains("Incompatible"));
    let reg = registry();
    match plan("neg_shape", &reg).1 {
        Err(Refusal::When {
            node,
            classid,
            truth,
            ..
        }) => {
            assert_eq!(
                (node.as_str(), classid, truth),
                ("n_add", 0x0F20, K3::False)
            )
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
}

/// `Acosh` has no registration: UNKNOWN, refused by signature.
#[test]
fn unregistered_op_is_refused() {
    let reg = registry();
    match plan("neg_unsupported", &reg).1 {
        Err(Refusal::Unregistered { node, signature }) => {
            assert_eq!(node, "n_abs");
            assert!(
                signature.starts_with("ai.onnx:Acosh(Some(F32))"),
                "{signature}"
            );
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
}

/// `com.example:Abs`: Tract imports it as the default-domain `Abs`; the source
/// domain keys the signature, so it is unregistered.
#[test]
fn foreign_domain_is_unregistered_although_tract_accepts_it() {
    assert!(ort()["variants"]["neg_domain"]["ort_error"]
        .as_str()
        .unwrap()
        .contains("com.example:Abs"));
    let reg = registry();
    match plan("neg_domain", &reg).1 {
        Err(Refusal::Unregistered { node, signature }) => {
            assert_eq!(node, "n_abs");
            assert!(signature.starts_with("com.example:Abs"), "{signature}");
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
}

/// A run-time fact the facts cannot show: a sum past int32 is refused, not wrapped.
#[test]
fn int32_overflow_is_refused_at_run_time() {
    let reg = registry();
    let (fx, p) = plan("base", &reg);
    let mut ins = inputs(None);
    ins[0].1 = Value::I32(ArrayD::from_shape_vec(IxDyn(&[3]), vec![i32::MAX, 1, 1]).unwrap());
    match p.unwrap().run(&fx.store, &ins) {
        Err(Refusal::Native(lance_graph_onnx::Refusal::OutOfDtypeRange(v))) => {
            assert_eq!(v, i32::MAX as i64 + 2)
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
}

/// The source keeps both `T = 0` and `Z = 0` as Property positions, although
/// Tract's inference model merges equal constants into one node.
#[test]
fn equal_initializers_stay_distinct_positions() {
    let (_, g) = graph("base");
    assert!(g.props.iter().any(|p| p == "T") && g.props.iter().any(|p| p == "Z"));
    let onnx = tract_onnx::onnx();
    let b = bytes("base");
    let names: Vec<String> = onnx
        .model_for_proto_model(&onnx.proto_model_for_read(&mut &*b).unwrap())
        .unwrap()
        .nodes()
        .iter()
        .map(|n| n.name.clone())
        .collect();
    assert!(
        names.contains(&"T".into()) && !names.contains(&"Z".into()),
        "{names:?}"
    );
}

/// The node list reversed in the protobuf (no longer topological): the
/// schedule comes from `dep`, not from source order, so the graph still runs
/// and matches ORT.
#[test]
fn schedule_comes_from_dep_not_source_order() {
    use prost::Message;
    let mut m = tract_onnx::pb::ModelProto::decode(&*bytes("base")).unwrap();
    m.graph.as_mut().unwrap().node.reverse();
    let b = m.encode_to_vec();
    let src = SourceInventory::from_bytes(&b).unwrap();
    assert_eq!(
        src.nodes[0].name, "n_div",
        "anti-vacuity: the source order is reversed"
    );
    let facts = tract_facts(&bytes("base"), &[]).unwrap();
    let g = OnnxGraph::build(&src, &facts).unwrap();
    let reg = registry();
    let store = FrameStore::new(revisions(&src, &reg, &g));
    let p = resolve(&src, g, &reg, &store).unwrap();
    assert_eq!(
        outputs(&p.run(&store, &inputs(None)).unwrap()),
        ort_out("base")
    );
}

/// Tract's shapes removed: the first shape guard in the schedule, `Greater`'s
/// scalar-threshold check, is UNKNOWN, and UNKNOWN refuses: it never counts as
/// TRUE. (Before the inference-stage facts, `T` had no Tract fact at all,
/// because the typed stage merges `T` and `Z`, so its shape came from the
/// source and the first UNKNOWN was `n_where`.)
#[test]
fn unknown_shapes_refuse() {
    let src = SourceInventory::from_bytes(&bytes("base")).unwrap();
    let mut facts = tract_facts(&bytes("base"), &[]).unwrap();
    for f in facts.values_mut() {
        f.shape = None;
    }
    let g = OnnxGraph::build(&src, &facts).unwrap();
    let reg = registry();
    let store = FrameStore::new(revisions(&src, &reg, &g));
    match resolve(&src, g, &reg, &store) {
        Err(Refusal::When { node, truth, .. }) => {
            assert_eq!((node.as_str(), truth), ("n_greater", K3::Unknown))
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
}

/// An input outside the facts the plan was resolved on is refused before any
/// node runs: `X` resolved as `[7]` (rank 1, what `ReduceSum`'s WHEN admitted)
/// supplied as `[2,3]`, or with the wrong dtype.
#[test]
fn inputs_outside_the_resolved_facts_are_refused() {
    let reg = registry();
    let (fx, p) = plan("base", &reg);
    let p = p.unwrap();
    let mut ins = inputs(None);
    ins[0].1 = Value::I32(ArrayD::from_shape_vec(IxDyn(&[2, 3]), vec![1; 6]).unwrap());
    match p.run(&fx.store, &ins) {
        Err(Refusal::Runtime { node, what }) => {
            assert_eq!(node, "X");
            assert!(what.contains("shape [2, 3]"), "{what}");
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
    let mut ins = inputs(None);
    ins[1].1 = Value::I32(ArrayD::from_shape_vec(IxDyn(&[2, 3]), vec![1; 6]).unwrap());
    assert!(matches!(
        p.run(&fx.store, &ins),
        Err(Refusal::Runtime { .. })
    ));
    // an initializer is not an input the caller may overwrite
    let mut ins = inputs(None);
    ins.push(("B", f32_value(&[3], &[0; 3])));
    assert!(matches!(
        p.run(&fx.store, &ins),
        Err(Refusal::Runtime { .. })
    ));
}

/// The inference stage gives a full fact (dtype and shape) for every source
/// value, the typed stage only for those that survive typing; where both
/// describe a value they agree.
#[test]
fn inference_stage_facts_cover_every_value_and_agree_with_typed() {
    use tract_harvest_probe::dr3::tract_fact_sources;
    for v in ["base", "div3", "neg_where_nonzero"] {
        let src = SourceInventory::from_bytes(&bytes(v)).unwrap();
        let fs = tract_fact_sources(&bytes(v), &[]).unwrap();
        let values: Vec<&String> = src.nodes.iter().flat_map(|n| &n.outputs).collect();
        let full = |m: &std::collections::HashMap<String, tract_harvest_probe::registry::Fact>| {
            values
                .iter()
                .filter(|o| {
                    m.get(o.as_str())
                        .is_some_and(|f| f.dtype.is_some() && f.shape.is_some())
                })
                .count()
        };
        assert_eq!(
            full(&fs.inference),
            values.len(),
            "{v}: inference covers all"
        );
        assert!(
            fs.disagreements().is_empty(),
            "{v}: {:?}",
            fs.disagreements()
        );
        let both = values
            .iter()
            .filter(|o| fs.inference.contains_key(o.as_str()) && fs.typed.contains_key(o.as_str()))
            .count();
        assert!(both > 0, "{v}: anti-vacuity, the stages overlap");
    }
}

/// `X`'s dimension removed from the input type: Tract's typed stage refuses
/// the graph, the inference stage still runs. `X`'s dtype is known, its shape
/// is not, and an undetermined dimension is never turned into a symbol (two
/// undetermined dimensions need not be equal). The plan then refuses at the
/// first guard that needs that shape.
#[test]
fn undetermined_input_dim_gives_no_shape_and_typing_failure_is_recorded() {
    use prost::Message;
    use tract_harvest_probe::dr3::tract_fact_sources;
    use tract_harvest_probe::value::DType;
    let mut m = tract_onnx::pb::ModelProto::decode(&*bytes("base")).unwrap();
    let x = m
        .graph
        .as_mut()
        .unwrap()
        .input
        .iter_mut()
        .find(|i| i.name == "X")
        .unwrap();
    let Some(tract_onnx::pb::type_proto::Value::TensorType(t)) =
        x.r#type.as_mut().and_then(|t| t.value.as_mut())
    else {
        panic!("X is a tensor");
    };
    t.shape.as_mut().unwrap().dim[0].value = None;
    let b = m.encode_to_vec();
    let fs = tract_fact_sources(&b, &[]).unwrap();
    assert!(
        fs.typed_error
            .as_deref()
            .is_some_and(|e| e.contains("determined fact")),
        "{:?}",
        fs.typed_error
    );
    assert!(fs.typed.is_empty());
    let x = &fs.inference["X"];
    assert_eq!((x.dtype, &x.shape), (Some(DType::I32), &None));
    // F is untouched and fully known: the stage did run.
    assert!(fs.inference["F"].shape.is_some());
    let src = SourceInventory::from_bytes(&b).unwrap();
    let g = OnnxGraph::build(&src, &fs.merged()).unwrap();
    let reg = registry();
    let store = FrameStore::new(revisions(&src, &reg, &g));
    match resolve(&src, g, &reg, &store) {
        Err(Refusal::When { truth, .. }) => assert_eq!(truth, K3::Unknown),
        other => panic!("{:?}", other.map(|_| ())),
    }
}

// ── D-TRACT-SHAPE-1: cold shape folding ─────────────────────────────────────

fn ort_f32(v: &str, out: &str) -> (Vec<usize>, Vec<u32>) {
    let e = &ort()["variants"][v]["ort"][out];
    let shape = e["shape"]
        .as_array()
        .unwrap()
        .iter()
        .map(|d| d.as_u64().unwrap() as usize)
        .collect();
    (shape, u32s(&e["bits"]))
}

fn f32_bits(m: &std::collections::HashMap<String, Value>, k: &str) -> (Vec<usize>, Vec<u32>) {
    match &m[k] {
        Value::F32(a) => (a.shape().to_vec(), a.iter().map(|v| v.to_bits()).collect()),
        other => panic!("{k}: {other:?}"),
    }
}

fn f_input() -> Value {
    f32_value(&[2, 3], &u32s(&ort()["inputs"]["F"]["bits"]))
}

/// Distance in units in the last place between two f32 (NaN only matches NaN).
fn ulp(a: f32, b: f32) -> u32 {
    if a.is_nan() || b.is_nan() {
        return if a.is_nan() && b.is_nan() {
            0
        } else {
            u32::MAX
        };
    }
    let key = |x: f32| {
        let b = x.to_bits() as i64;
        if b & 0x8000_0000 != 0 {
            0x8000_0000 - b
        } else {
            b
        }
    };
    (key(a) - key(b)).unsigned_abs() as u32
}

/// `Concat(Unsqueeze(Gather(Shape(F), 1), [0]), [-1])` depends on F's shape
/// only, which the facts know: it folds at resolution through the registered
/// DOs. `Reshape(F, ·)` and `Unsqueeze(F, ·)` read F's values and run. The run
/// agrees with ORT bit for bit.
#[test]
fn shape_chain_folds_and_the_data_nodes_run_against_ort() {
    let reg = registry();
    let (fx, p) = plan("shape_fold", &reg);
    let p = p.unwrap();
    let folded: Vec<(&str, u16)> = p
        .folded
        .iter()
        .map(|b| (b.name.as_str(), b.classid))
        .collect();
    assert_eq!(
        folded,
        [
            ("n_shape", 0x0F60),
            ("n_gather", 0x0F64),
            ("n_unsq_d", 0x0F65),
            ("n_concat", 0x0F67)
        ]
    );
    let steps: Vec<(&str, u16)> = p
        .steps
        .iter()
        .map(|b| (b.name.as_str(), b.classid))
        .collect();
    assert_eq!(steps, [("n_reshape", 0x0F6A), ("n_unsq_f", 0x0F66)]);
    let t = p.graph.props.iter().position(|n| n == "t").unwrap();
    assert_eq!(
        p.graph.consts[t].as_ref().and_then(Value::i64s),
        Some(vec![3, -1])
    );
    let out = p.run(&fx.store, &[("F", f_input())]).unwrap();
    assert_eq!(f32_bits(&out, "R"), ort_f32("shape_fold", "R"));
    assert_eq!(f32_bits(&out, "U"), ort_f32("shape_fold", "U"));
}

/// The folded target `[3, -1]` was computed from F's resolved shape [2, 3]. A
/// run with another F shape is refused before any step, so the fold is never
/// applied to an input it was not computed for.
#[test]
fn folded_shapes_refuse_a_run_with_other_input_dims() {
    let reg = registry();
    let (fx, p) = plan("shape_fold", &reg);
    let p = p.unwrap();
    let f = Value::F32(ArrayD::zeros(IxDyn(&[3, 2])));
    match p.run(&fx.store, &[("F", f)]) {
        Err(Refusal::Runtime { node, what }) => {
            assert_eq!(node, "F");
            assert!(what.contains("resolved for"), "{what}");
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
}

/// F's shape is fully known, yet `Unsqueeze(F)` and `Reshape(F, ·)` read F's
/// values: their class is Data and neither folds.
#[test]
fn a_node_reading_input_values_never_folds() {
    use tract_harvest_probe::fold::{classify, fold, Dep};
    let b = bytes("shape_fold");
    let src = SourceInventory::from_bytes(&b).unwrap();
    let facts = tract_facts(&b, &[]).unwrap();
    let (_, dep) = classify(&src, &facts);
    let by: Vec<(&str, Dep)> = src.nodes.iter().map(|n| n.name.as_str()).zip(dep).collect();
    assert_eq!(
        by,
        [
            ("n_shape", Dep::Shape),
            ("n_gather", Dep::Shape),
            ("n_unsq_d", Dep::Shape),
            ("n_concat", Dep::Shape),
            ("n_reshape", Dep::Data),
            ("n_unsq_f", Dep::Data)
        ]
    );
    let f = fold(&src, &facts, &registry());
    assert!(!f.values.contains_key("R") && !f.values.contains_key("U"));
}

/// Over `X float[N]` the same chain has a symbolic dimension: nothing folds
/// (the symbol is not a value), the Reshape target is not a constant, and its
/// WHEN is UNKNOWN, which resolution refuses rather than treating as TRUE.
#[test]
fn a_symbolic_shape_is_not_folded_and_unknown_is_not_true() {
    use tract_harvest_probe::fold::{classify, fold, Dep};
    let b = bytes("shape_sym");
    let src = SourceInventory::from_bytes(&b).unwrap();
    let facts = tract_facts(&b, &[]).unwrap();
    let (_, dep) = classify(&src, &facts);
    assert_eq!(dep[0], Dep::Symbolic, "Shape(X) of X[N]");
    assert!(dep.iter().all(|d| *d >= Dep::Symbolic));
    assert!(fold(&src, &facts, &registry()).nodes.is_empty());
    let reg = registry();
    match plan("shape_sym", &reg).1 {
        Err(Refusal::When {
            node,
            classid,
            truth,
            ..
        }) => {
            assert_eq!(
                (node.as_str(), classid, truth),
                ("n_reshape", 0x0F6A, K3::Unknown)
            );
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
}

